"""Content banks for validation/evaluation generation (authored for WS1; noun-free member/non-member descriptions,
shared head nouns, stratum-specific defining configurations, causal events with patient named once).
Every bank is used by generate_splits.py; nothing here is derived from evaluation outcomes."""

# ---------------------------------------------------------------------------------------------- recognition frames
# Observation-type frames that fit any physical stuff/object. {NP}: referent NP (lower-case, with determiner);
# {Ag}: agent.  Frames are partitioned between validation (V) and evaluation (E) so templates never cross splits.
FRAMES = {
    "subject": {"V": ["{NP} caught the low morning light.", "{NP} drew a curious look from the visitor.",
                      "{NP} appeared in the corner of the photograph."],
                "E": ["{NP} looked exactly as it had the day before.", "{NP} was the first thing the inspector noticed.",
                      "{NP} glinted faintly under the overhead tubes.", "{NP} showed a thin film of dust.",
                      "{NP} stayed in plain view for the whole afternoon.", "{NP} featured in the second slide of the talk."]},
    "passive_subject": {"V": ["{NP} was photographed for the catalogue.", "{NP} was sketched by a visiting art student."],
                        "E": ["{NP} was described in detail in the field notes.", "{NP} was mentioned twice in the morning report.",
                              "{NP} was filmed for a short training video.", "{NP} was listed under item four on the form."]},
    "direct_object": {"V": ["{Ag} photographed {NP} from several angles.", "{Ag} pointed out {NP} to a colleague."],
                      "E": ["{Ag} described {NP} in a short note.", "{Ag} sketched {NP} in soft pencil.",
                            "{Ag} noticed {NP} straight away.", "{Ag} recorded {NP} in the inventory."]},
    "prepositional_object": {"V": ["{Ag} glanced at {NP} for a moment.", "{Ag} wrote a brief comment about {NP}."],
                             "E": ["{Ag} leaned closer to {NP}.", "{Ag} talked for a minute about {NP}.",
                                   "{Ag} pointed at {NP} and nodded.", "{Ag} asked a question about {NP}."]},
    "indirect_object": {"V": ["{Ag} gave {NP} a careful look."], "E": ["{Ag} gave {NP} one more glance.", "{Ag} gave {NP} a long, thoughtful stare."]},
    "genitive_complement": {"V": ["The outline of {NP} showed clearly in the picture."],
                            "E": ["The colour of {NP} stood out against the background.", "The shape of {NP} was easy to see from the doorway."]},
}
FAMILY_ROLES = {"physical_impact": ["subject", "passive_subject", "direct_object", "prepositional_object", "indirect_object", "genitive_complement"],
                "heating": ["subject", "passive_subject", "direct_object", "prepositional_object"],
                "cutting": ["subject", "passive_subject", "direct_object", "prepositional_object"]}
